<script lang="ts">
 import {api,bootstrap,message} from './workspace';import Icon from './Icon.svelte';
 let username='',password='',busy=false,error='';
 async function login(){busy=true;error='';try{await api.call('login',{},new URLSearchParams({username,password}));password='';await bootstrap();}catch(e){error=e instanceof Error&&'status'in e&&e.status===403?'That username or password wasn’t recognized.':message(e);}finally{busy=false;}}
</script>
<div class="signin-wrap"><div class="signin-story"><span class="eyebrow">REGENERATE SKAGIT · RAFT</span><h1>Follow a little<br/>curiosity.</h1><p>Your own experiment. A little company.<br/>Something new to take with you.</p><div class="signin-illustration" aria-hidden="true"><svg viewBox="0 0 480 260" fill="none"><path d="M50 205c65-25 87 20 155 0s90-20 150 0 65 10 85-2M25 228c65-25 87 20 155 0s90-20 150 0 65 10 85-2" stroke="currentColor" stroke-width="1.3"/><path d="m140 174 180 0-32 25H172Zm90-120v118M230 58l72 94h-72Z" stroke="currentColor" stroke-width="2"/><circle cx="365" cy="66" r="25" stroke="currentColor"/></svg></div><span class="fine">Small experiments. Shared learning. Rooted here.</span></div>
 <form class="signin-card" on:submit|preventDefault={login}><span class="mini-mark"><Icon name="leaf" size={24}/></span><h2>Welcome to your workspace</h2><p>Sign in to pick up where your curiosity left off.</p><label for="username">Username<input id="username" autocomplete="username" bind:value={username} required/></label><label for="password">Password<input id="password" type="password" autocomplete="current-password" bind:value={password} required/></label>{#if error}<p class="alert" role="alert">{error}</p>{/if}<button class="button primary" disabled={busy}>{busy?'Signing in…':'Sign in'}<Icon name="arrow" size={17}/></button><p class="fine privacy-line"><Icon name="lock" size={14}/> Your drafts are private. Your work stays yours.</p><a class="text-link" href="https://regenerateskagit.org/">Visit Regenerate Skagit <span>↗</span></a></form>
